	@ConfigItem(
		name = "Chest/Clam Timer",
		description = "Display an infobox timer when the chest/clam moves.",
		position = 7,
		keyName = CONFIG_KEY_CHEST_CLAM_TIMER,
		section = SECTION_GENERAL
